  "summary": "The code contains critical security and performance flaws, specifically path traversal vulnerabilities and blocking synchronous I/O. The overall health is poor, requiring immediate refactoring to asynchronous patterns and strict input sanitization.",
  "fixed_code": "const express = require('express');\nconst fs = require('fs').promises;\nconst path = require('path');\nconst app = express();\n\nconst FILES_DIR = path.join(__dirname, 'files');\n\napp.get('/read', async (req, res) => {\n    const filename = req.query.filename;\n    if (!filename || typeof filename !== 'string') {\n        return res.status(400).send('Invalid or missing filename');\n    }\n\n    const safePath = path.normalize(path.join(FILES_DIR, filename));\n    if (!safePath.startsWith(FILES_DIR)) {\n        return res.status(403).send('Access denied');\n    }\n\n    try {\n        const data = await fs.readFile(safePath, 'utf8');\n        res.send(data);\n    } catch (err) {\n        res.status(404).send('File not found');\n    }\n});\n\napp.listen(3000);"
